/// <summary>
/// Data contract class that defines dialog parameters for the con demo job history scan operation.
/// </summary>
[DataContractAttribute]
public class ConDemoJobHistoryScanContract
{
    private str packedQuery;

}

Method.Source:
/// <summary>
/// Gets or sets the query the batch job runs, packed into a string.
/// </summary>
/// <param name = "_packedQuery">The packed query.</param>
/// <returns>The packed query.</returns>
/// <remarks>
/// The contract is serialised into the batch record, so the query is stored PACKED (a string),
/// never as a Query object. AifQueryTypeAttribute names the AOT query whose ranges the dialog renders.
/// </remarks>
[DataMemberAttribute('Query'), AifQueryTypeAttribute('_packedQuery', queryStr(BatchJobHistoryCleanUp))]
public str parmQuery(str _packedQuery = packedQuery)
{
    packedQuery = _packedQuery;

    return packedQuery;
}
